'use client';

import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { usePointerDrag } from './use-pointer-drag';
import { useReducedMotion } from './use-reduced-motion';
import './inertia-drag-surface.css';

export interface InertiaDragSurfaceProps {
  /** Accessible name for the stage. */
  label: string;
  /** Size of the object, in pixels. */
  size?: number;
  /** How quickly a throw slows down (0–1; higher glides longer). */
  friction?: number;
  className?: string;
}

const useIsomorphicLayoutEffect =
  typeof window === 'undefined' ? useEffect : useLayoutEffect;

/**
 * Drag the puck and let go: it keeps moving, slows down and stops inside the
 * stage, bouncing softly off the edges. Arrow buttons nudge it and Reset
 * centers it. With reduced motion it stops where you let go.
 */
export function InertiaDragSurface({
  label,
  size = 48,
  friction = 0.94,
  className = '',
}: InertiaDragSurfaceProps) {
  const stage = useRef<HTMLDivElement>(null);
  const [bounds, setBounds] = useState({ w: 0, h: 0 });
  const [pos, setPos] = useState({ x: 0, y: 0 });
  const [moving, setMoving] = useState(false);
  const frame = useRef(0);
  const origin = useRef(pos);
  // The live position, updated synchronously so a throw starts exactly
  // where the pointer let go, even before React re-renders.
  const latest = useRef(pos);
  const place = (p: { x: number; y: number }) => {
    latest.current = p;
    setPos(p);
  };
  const reduced = useReducedMotion();

  useIsomorphicLayoutEffect(() => {
    const el = stage.current;
    if (!el) return;
    const w = el.clientWidth - size;
    const h = el.clientHeight - size;
    setBounds({ w, h });
    place({ x: w / 2, y: h / 2 });
  }, [size]);

  useEffect(() => () => cancelAnimationFrame(frame.current), []);

  const clamp = (p: { x: number; y: number }) => ({
    x: Math.max(0, Math.min(bounds.w, p.x)),
    y: Math.max(0, Math.min(bounds.h, p.y)),
  });

  const glide = (vx: number, vy: number) => {
    cancelAnimationFrame(frame.current);
    if (reduced) return;
    let v = { x: vx * 12, y: vy * 12 };
    let p = { ...latest.current };
    setMoving(true);
    const tick = () => {
      p = { x: p.x + v.x, y: p.y + v.y };
      if (p.x < 0 || p.x > bounds.w) v.x *= -0.5;
      if (p.y < 0 || p.y > bounds.h) v.y *= -0.5;
      p = clamp(p);
      v = { x: v.x * friction, y: v.y * friction };
      place(p);
      if (Math.hypot(v.x, v.y) > 0.15)
        frame.current = requestAnimationFrame(tick);
      else setMoving(false);
    };
    frame.current = requestAnimationFrame(tick);
  };

  const drag = usePointerDrag({
    onStart: () => {
      cancelAnimationFrame(frame.current);
      setMoving(false);
      origin.current = latest.current;
    },
    onMove: ({ dx, dy }) =>
      place(clamp({ x: origin.current.x + dx, y: origin.current.y + dy })),
    onEnd: ({ vx, vy }) => glide(vx, vy),
  });

  const nudge = (dx: number, dy: number) => {
    if (reduced)
      place(
        clamp({ x: latest.current.x + dx * 40, y: latest.current.y + dy * 40 })
      );
    else glide(dx * 0.6, dy * 0.6);
  };

  return (
    <div className={`mg-inertia ${className}`}>
      <div
        ref={stage}
        className='mg-inertia__stage'
        role='group'
        aria-label={label}
      >
        <div
          className='mg-inertia__puck'
          data-moving={moving}
          style={{
            width: size,
            height: size,
            transform: `translate(${pos.x}px, ${pos.y}px)`,
          }}
          aria-hidden='true'
          {...drag}
        />
      </div>
      <div className='mg-inertia__controls'>
        <button
          type='button'
          aria-label='Throw left'
          onClick={() => nudge(-1, 0)}
        >
          ←
        </button>
        <button
          type='button'
          aria-label='Throw up'
          onClick={() => nudge(0, -1)}
        >
          ↑
        </button>
        <button
          type='button'
          aria-label='Throw down'
          onClick={() => nudge(0, 1)}
        >
          ↓
        </button>
        <button
          type='button'
          aria-label='Throw right'
          onClick={() => nudge(1, 0)}
        >
          →
        </button>
        <button
          type='button'
          onClick={() => {
            cancelAnimationFrame(frame.current);
            setMoving(false);
            place({ x: bounds.w / 2, y: bounds.h / 2 });
          }}
        >
          Reset
        </button>
        <span className='mg-inertia__pos' role='status'>
          {moving ? 'Moving' : 'At rest'} · x {Math.round(pos.x)}, y{' '}
          {Math.round(pos.y)}
        </span>
      </div>
    </div>
  );
}

.mg-inertia {
  display: grid;
  gap: 10px;
  color: var(--mg-ink, #0c1738);
}

.mg-inertia__stage {
  position: relative;
  height: 180px;
  overflow: hidden;
  border: 1px solid var(--mg-line, #d6def2);
  border-radius: 14px;
  background:
    radial-gradient(#c7d2ef 1px, transparent 1px) 0 0 / 16px 16px,
    #fff;
}

.mg-inertia__puck {
  position: absolute;
  top: 0;
  left: 0;
  border-radius: 50%;
  background: var(--mg-accent, #164cff);
  box-shadow:
    inset 0 0 0 6px rgba(255, 255, 255, 0.25),
    0 10px 20px -10px rgba(12, 23, 56, 0.6);
  cursor: grab;
  touch-action: none;
}

.mg-inertia__puck[data-moving='true'] {
  background: var(--mg-ink, #0c1738);
}

.mg-inertia__controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}

.mg-inertia__controls button {
  min-width: 44px;
  min-height: 44px;
  padding: 0 10px;
  border: 1px solid var(--mg-line-strong, #b9c5e6);
  border-radius: 8px;
  background: #fff;
  color: inherit;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.mg-inertia__controls button:focus-visible {
  outline: 2px solid var(--mg-accent, #164cff);
  outline-offset: 2px;
}

.mg-inertia__pos {
  color: #46527a;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}

@media (prefers-reduced-motion: reduce) {
  .mg-inertia__puck {
    transition: none;
  }
}

'use client';

import { useRef, type PointerEvent as ReactPointerEvent } from 'react';

export interface DragState {
  /** Distance from where the drag started, in pixels. */
  dx: number;
  dy: number;
  /** Pointer position in viewport coordinates. */
  clientX: number;
  clientY: number;
  /** Smoothed velocity in pixels per millisecond. */
  vx: number;
  vy: number;
}

export interface PointerDragOptions {
  /** Return false to ignore this press. */
  onStart?: (event: ReactPointerEvent<HTMLElement>) => boolean | void;
  onMove?: (drag: DragState) => void;
  /**
   * `cancelled` is true when the browser took the gesture over, for example
   * to scroll the page on touch.
   */
  onEnd?: (drag: DragState, cancelled: boolean) => void;
}

interface Active {
  id: number;
  startX: number;
  startY: number;
  lastX: number;
  lastY: number;
  lastTime: number;
  vx: number;
  vy: number;
}

/**
 * Pointer-capture dragging for mouse, pen and touch. Spread the returned
 * handlers on the element that starts the drag. Pair it with a CSS
 * `touch-action` that leaves the scroll axis you still want to the browser.
 */
export function usePointerDrag(options: PointerDragOptions) {
  const latest = useRef(options);
  latest.current = options;
  const active = useRef<Active | null>(null);

  const snapshot = (a: Active, x: number, y: number): DragState => ({
    dx: x - a.startX,
    dy: y - a.startY,
    clientX: x,
    clientY: y,
    vx: a.vx,
    vy: a.vy,
  });

  const finish = (
    event: ReactPointerEvent<HTMLElement>,
    cancelled: boolean
  ) => {
    const a = active.current;
    if (!a || a.id !== event.pointerId) return;
    active.current = null;
    if (event.currentTarget.hasPointerCapture?.(event.pointerId))
      event.currentTarget.releasePointerCapture(event.pointerId);
    // A pause before release means the pointer was not really flung.
    if (event.timeStamp - a.lastTime > 150) {
      a.vx = 0;
      a.vy = 0;
    }
    latest.current.onEnd?.(
      snapshot(a, event.clientX, event.clientY),
      cancelled
    );
  };

  return {
    onPointerDown(event: ReactPointerEvent<HTMLElement>) {
      if (event.button !== 0 || active.current) return;
      if (latest.current.onStart?.(event) === false) return;
      event.currentTarget.setPointerCapture?.(event.pointerId);
      active.current = {
        id: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        lastX: event.clientX,
        lastY: event.clientY,
        lastTime: event.timeStamp,
        vx: 0,
        vy: 0,
      };
    },
    onPointerMove(event: ReactPointerEvent<HTMLElement>) {
      const a = active.current;
      if (!a || a.id !== event.pointerId) return;
      const dt = Math.max(1, event.timeStamp - a.lastTime);
      a.vx = a.vx * 0.6 + ((event.clientX - a.lastX) / dt) * 0.4;
      a.vy = a.vy * 0.6 + ((event.clientY - a.lastY) / dt) * 0.4;
      a.lastX = event.clientX;
      a.lastY = event.clientY;
      a.lastTime = event.timeStamp;
      latest.current.onMove?.(snapshot(a, event.clientX, event.clientY));
    },
    onPointerUp(event: ReactPointerEvent<HTMLElement>) {
      finish(event, false);
    },
    onPointerCancel(event: ReactPointerEvent<HTMLElement>) {
      finish(event, true);
    },
  };
}

'use client';

import { useEffect, useState } from 'react';

/** True when the user has asked for reduced motion. Follows live changes. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const query = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener('change', update);
    return () => query.removeEventListener('change', update);
  }, []);
  return reduced;
}
